head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징


scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF15611.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 자산운용사(위탁운영업체)
    dts_TrstComList.DataID = "/CodeAction.do?method=listTrstComCB" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R";
    dts_TrstComList.Reset();

    // 상품유형
    dts_IdxLvrgInvrsCd.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=IDX_LVRG_INVRS_TP_CD";
    dts_IdxLvrgInvrsCd.Reset();
};
scwin.fn_CheckCond = function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    scwin.fn_Search();
};
scwin.fn_Search = function() {
    var gIdxCd = $c.cp.valueOfIndex(cmd_IdxliTpCd, "VALUE", cmd_IdxliTpCd.getSelectedIndex());
    var gSubmit = $c.cp.valueOfIndex(cmd_Submit, "VALUE", cmd_Submit.getSelectedIndex());
    var url = "/DsclSearchEtf.do?method=listETFLvrgInvrsSrch" + "&inputMessageId=LVRGINVRSLIST_INOUT" + "&outputMessageId=LVRGINVRSLIST_INOUT" + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&TRST_COM_ISUR_CD=" + $c.stf.getObjectValue(cmb_TrstCom) + "&IDX_LVRG_INVRS_TP_CD=" + gIdxCd + "&SUBMIT_YN=" + gSubmit + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.cm.ShowWin(grd_Grid); //LOADING 이미지

    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_DsclList.getCellData(eval(obj), "ISUR_CD");
};
scwin.btn_Search_onclick = function() {
    scwin.fn_CheckCond();
};
scwin.btn_Excel_onclick = function() {
    $c.data.downloadGridViewExcel(grd_Grid, "ETF레버리지인버스 상품관리", "", "8");
};
scwin.dts_DsclList_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    if (dts_DsclList.errorMsg) {
        $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
    } else {
        txb_total.setValue(rowcount + "  종목");
        if (rowcount > 0) {
            txb_IsuTotal.setValue(dts_DsclList.getCellData(1, "SUBMITCNT") + "  종목");
        } else {
            txb_IsuTotal.setValue("0  종목");
        }
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //조회완료시 LOADING 이미지 종료

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "ISU_KOR_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.dts_IdxLvrgInvrsCd_OnFilter = function(row) {
    if (dts_IdxLvrgInvrsCd.getCellData(row, "value") == "P1") {
        //'일반'은 보이지 않게 처리
        return false;
    } else {
        return true;
    }
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_CheckCond();
};
